    function run(address caller, string calldata desc) public payable {
        require(true);
        bool reverted;
        try c.newEmergencyOracle(desc) { reverted = false; } catch { reverted = true; }
        assert(caller != c.jojoTeam() ? reverted : true);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller) public payable {
        require(caller != c.jojoTeam());
        bool reverted; try c.newEmergencyOracle("") { reverted = false; } catch { reverted = true; }
        assert(reverted == true);
    }
}

