pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address public jojoTeam = address(0xdead);

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(string calldata description) public {
        if (bytes(description).length > 0) {
            (bool ok, bytes memory data) = address(c).call(
                abi.encodeWithSignature("newEmergencyOracle(string)", description)
            );
            if (ok) {
                (bool ok2, bytes memory eventData) = address(c).call(
                    abi.encodeWithSignature("NewEmergencyOracle(address,address)")
                );
                if (ok2) {
                    (address deployer, address newOracle) = abi.decode(eventData, (address, address));
                    (bool callOk, bytes memory ownerData) = address(newOracle).staticcall(
                        abi.encodeWithSignature("owner()")
                    );
                    if (callOk) {
                        address oracleOwner = abi.decode(ownerData, (address));
                        assertTrue(oracleOwner != address(0));
                    }
                }
            }
        }
    }
}

