pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
        // Make caller the JOJO team to pass onlyJojoTeam modifier
        vm.prank(address(this));
        c.jojoTeam = address(this);
    }

    function testFuzz_property(string calldata description) public {
        // Admissible domain: any string (fuzzer explores length and content)
        vm.prank(address(this));
        try c.newEmergencyOracle(description) returns (address newOracle) {
            // After successful deployment, read back the stored description from the created EmergencyOracle
            string memory storedDescription = EmergencyOracle(newOracle).description();
            // General rule: stored description must equal the argument passed to newEmergencyOracle
            assertTrue(keccak256(abi.encodePacked(storedDescription)) == keccak256(abi.encodePacked(description)));
        } catch {
            // If the call reverts (e.g. deploy fails), this input is not admissible for the property; skip
        }
    }
}
